typedef unsigned int MENU_UINT32;
typedef unsigned short MENU_UINT16;
typedef unsigned char MENU_UINT8;

const int maxmenulines = 16;
const int maxmenulinelength = 64;
const int MAXMENUCMD = 16;

typedef char MenuLine[maxmenulinelength];

struct MenuColor
{
  MENU_UINT8 r, g, b, a;
};

struct MenuRect
{
  MENU_UINT16 x0, y0, x1, y1;
};

class Menu;

class MenuRender
{
  MenuRect limit;
  MenuRect inuse;
  MenuLine text[maxmenulines];
  MENU_UINT32 state[maxmenulines];
  int active;
  int topentry;

public:
  virtual ~MenuRender();
  virtual void OpenMenu(Menu *);
  virtual void CloseMenu(void);

protected:
  virtual int TotalEntries(void) = 0;
  virtual MENU_UINT32 GetElementState(int) = 0;
  virtual void GetElementText(int, char *, int) = 0;
  virtual MenuColor GetElementColor(int) = 0;
};

class MenuInput
{
  unsigned char bstate[MAXMENUCMD];

public:
  virtual ~MenuInput();

protected:
  virtual void ButtonPress(int) = 0;
  virtual void ButtonRelease(int) = 0;
};

class MenuSystem : public MenuRender, public MenuInput
{
  Menu *curmenu;

protected:
  virtual int TotalEntries(void);
  virtual MENU_UINT32 GetElementState(int);
  virtual void GetElementText(int, char *, int);
  virtual MenuColor GetElementColor(int);
};

class Menu
{
public:
  MenuColor GetElementColor(int);
};

MenuColor menubackground = { 0, 0, 0, 192 };

MenuColor MenuSystem::GetElementColor( int i )
{
	if ( curmenu )
		return curmenu->GetElementColor(i);
	else
		return menubackground;
}
